<template>
  <div class="app-container">
    <el-row :gutter="16">
      <el-col :span="14"><el-card><template #header><span>外管礼包</span><el-button type="primary" size="small" style="float:right" @click="newPack">新增礼包</el-button></template><el-table :data="packs"><el-table-column prop="giftName" label="礼包"/><el-table-column prop="goldAmount" label="金币"/><el-table-column prop="receiveLimit" label="每人限领"/><el-table-column label="内容"><template #default="{row}">{{ itemText(row.items) }}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status === '0' ? 'success' : 'info'">{{ row.status === '0' ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="primary" @click="editPack(row)">编辑</el-button></template></el-table-column></el-table></el-card></el-col>
      <el-col :span="10"><el-card><template #header>账号礼包额度</template><el-form label-width="90px"><el-form-item label="外管账号"><el-select v-model="quota.accountId" filterable style="width:100%"><el-option v-for="item in accounts" :key="item.id" :label="`${item.loginName}（${item.realName}）`" :value="item.id" /></el-select></el-form-item><el-form-item label="礼包"><el-select v-model="quota.giftId" style="width:100%"><el-option v-for="item in packs" :key="item.id" :label="item.giftName" :value="item.id" /></el-select></el-form-item><el-form-item label="次数额度"><el-input-number v-model="quota.quotaCount" :min="0" /></el-form-item><el-button type="primary" @click="saveQuota">保存额度</el-button></el-form><el-table :data="quotas" size="small" style="margin-top:16px"><el-table-column prop="loginName" label="账号"/><el-table-column prop="giftName" label="礼包"/><el-table-column label="剩余"><template #default="{row}">{{ row.quotaCount - row.usedCount }} / {{ row.quotaCount }}</template></el-table-column></el-table></el-card></el-col>
    </el-row>
    <el-dialog v-model="visible" :title="form.id ? '编辑礼包' : '新增礼包'" width="650px"><el-form label-width="100px"><el-form-item label="礼包名称"><el-input v-model="form.giftName" /></el-form-item><el-form-item label="金币"><el-input-number v-model="form.goldAmount" :min="0" /></el-form-item><el-form-item label="每人限领"><el-input-number v-model="form.receiveLimit" :min="1" /></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio value="0">启用</el-radio><el-radio value="1">停用</el-radio></el-radio-group></el-form-item><el-divider>礼包内容</el-divider><div v-for="(item,index) in form.items" :key="index" class="item"><el-select v-model="item.itemType" style="width:110px"><el-option label="装扮" value="PROP"/><el-option label="VIP卡" value="VIP"/></el-select><el-input v-if="item.itemType === 'PROP'" v-model.number="item.propId" placeholder="装扮ID"/><el-select v-else v-model="item.vipLevel"><el-option label="VIP1" :value="1000"/><el-option label="VIP2" :value="2000"/><el-option label="VIP3" :value="3000"/></el-select><el-input-number v-model="item.dayNum" :min="1"/><el-input-number v-model="item.quantity" :min="1"/><el-button link type="danger" @click="form.items.splice(index,1)">删除</el-button></div><el-button link type="primary" @click="form.items.push({itemType:'PROP',propId:null,dayNum:30,quantity:1})">新增内容</el-button></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="savePack">保存</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { ElMessage } from 'element-plus'
import { listExternalAccount, listExternalGiftPackQuotas, listExternalGiftPacks, saveExternalGiftPack, saveExternalGiftPackQuota } from '@/api/external/manager'
const packs = ref([]); const accounts = ref([]); const quotas = ref([]); const visible = ref(false); const quota = reactive({ accountId: null, giftId: null, quotaCount: 0 }); const form = reactive({})
const itemText = items => (items || []).map(item => item.itemType === 'VIP' ? `VIP${item.vipLevel / 1000} ${item.dayNum}天` : `装扮${item.propId} ${item.dayNum}天`).join('、')
function resetForm() { Object.assign(form, { id: null, giftName: '', goldAmount: 0, receiveLimit: 1, status: '0', items: [{ itemType: 'PROP', propId: null, dayNum: 30, quantity: 1 }] }) }
function newPack() { resetForm(); visible.value = true }
function editPack(row) { Object.assign(form, JSON.parse(JSON.stringify(row))); visible.value = true }
async function load() { const [packRes, accountRes, quotaRes] = await Promise.all([listExternalGiftPacks(), listExternalAccount({ pageNum: 1, pageSize: 100 }), listExternalGiftPackQuotas({ all: true })]); packs.value = packRes.data; accounts.value = accountRes.rows; quotas.value = quotaRes.data }
async function savePack() { await saveExternalGiftPack(form); ElMessage.success('保存成功'); visible.value = false; await load() }
async function saveQuota() { if (!quota.accountId || !quota.giftId) return ElMessage.warning('请选择账号和礼包'); await saveExternalGiftPackQuota(quota); ElMessage.success('额度已保存'); await load() }
load()
</script>
<style scoped>.item{display:grid;grid-template-columns:110px 1fr 120px 120px 44px;gap:8px;margin-bottom:8px;align-items:center}</style>
